CREATE OR REPLACE FUNCTION public.is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text='superadmin') $$;
CREATE OR REPLACE FUNCTION public.is_facility_admin(_facility uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_platform_admin() OR EXISTS(SELECT 1 FROM public.user_facilities WHERE user_id=auth.uid() AND facility_id=_facility AND role::text IN ('facility_admin','admin')) $$;
CREATE OR REPLACE FUNCTION public.has_facility_access(_facility uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_platform_admin() OR EXISTS(SELECT 1 FROM public.user_facilities WHERE user_id=auth.uid() AND facility_id=_facility) $$;
CREATE OR REPLACE FUNCTION public.facility_has_role(_facility uuid, _roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_platform_admin() OR EXISTS(SELECT 1 FROM public.user_facilities uf WHERE uf.user_id=auth.uid() AND uf.facility_id=_facility AND (uf.role::text=ANY(_roles) OR (uf.role IS NULL AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=auth.uid() AND ur.role::text=ANY(_roles) AND ur.role::text NOT IN ('superadmin','facility_admin'))))) $$;
CREATE OR REPLACE FUNCTION public.hr_can_manage(_facility uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.facilities WHERE id=_facility AND is_active) AND NOT EXISTS(SELECT 1 FROM public.facility_modules WHERE facility_id=_facility AND module='hr' AND NOT enabled) AND (public.is_facility_admin(_facility) OR public.facility_has_role(_facility, ARRAY['hr_officer','hr_manager'])) $$;
REVOKE ALL ON FUNCTION public.is_platform_admin(), public.is_facility_admin(uuid), public.facility_has_role(uuid,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_platform_admin(), public.is_facility_admin(uuid), public.facility_has_role(uuid,text[]) TO authenticated,service_role;
DROP POLICY IF EXISTS "Admins can manage roles" ON public.user_roles;
CREATE POLICY "Platform administrators manage global roles" ON public.user_roles FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
DROP POLICY IF EXISTS "Users can view own roles" ON public.user_roles;
CREATE POLICY "Own or platform global roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_platform_admin());
DROP POLICY IF EXISTS "facilities admin write" ON public.facilities;
CREATE POLICY "Platform administrators manage facilities" ON public.facilities FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
DROP POLICY IF EXISTS "facilities read" ON public.facilities;
CREATE POLICY "Authorized facility reads" ON public.facilities FOR SELECT TO authenticated USING(public.has_facility_access(id) AND (is_active OR public.is_platform_admin()));
DROP POLICY IF EXISTS "facility_modules admin write" ON public.facility_modules;
CREATE POLICY "Platform administrators manage modules" ON public.facility_modules FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
DROP POLICY IF EXISTS "facility_modules read" ON public.facility_modules;
CREATE POLICY "Authorized module reads" ON public.facility_modules FOR SELECT TO authenticated USING(public.has_facility_access(facility_id));
DROP POLICY IF EXISTS "user_facilities admin write" ON public.user_facilities;
CREATE POLICY "Platform administrators manage memberships" ON public.user_facilities FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
DROP POLICY IF EXISTS "user_facilities own or admin" ON public.user_facilities;
CREATE POLICY "Own or branch administrator memberships" ON public.user_facilities FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_facility_admin(facility_id));
CREATE OR REPLACE FUNCTION public.assign_facility_staff(_facility uuid,_user uuid,_role text,_remove boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE platform boolean := public.is_platform_admin();
BEGIN
 IF NOT public.is_facility_admin(_facility) THEN RAISE EXCEPTION 'Branch administrator access required' USING ERRCODE='42501'; END IF;
 IF NOT platform AND (NOT EXISTS(SELECT 1 FROM public.user_facilities WHERE facility_id=_facility AND user_id=_user) OR _user=auth.uid() OR EXISTS(SELECT 1 FROM public.user_facilities WHERE facility_id=_facility AND user_id=_user AND role::text IN ('admin','facility_admin'))) THEN RAISE EXCEPTION 'Only platform administrators can change administrator assignments or add accounts from another branch' USING ERRCODE='42501'; END IF;
 IF _remove THEN DELETE FROM public.user_facilities WHERE facility_id=_facility AND user_id=_user; RETURN; END IF;
 IF _role IN ('superadmin','admin','patient','athlete') OR (NOT platform AND _role='facility_admin') THEN RAISE EXCEPTION 'Invalid branch staff role' USING ERRCODE='42501'; END IF;
 IF _role <> 'facility_admin' AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role::text=_role) THEN RAISE EXCEPTION 'Select an existing staff role'; END IF;
 INSERT INTO public.user_facilities(user_id,facility_id,role) VALUES(_user,_facility,_role::public.app_role) ON CONFLICT(user_id,facility_id) DO UPDATE SET role=EXCLUDED.role;
END $$;
REVOKE ALL ON FUNCTION public.assign_facility_staff(uuid,uuid,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_facility_staff(uuid,uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.facility_staff_options(_facility uuid) RETURNS TABLE(user_id uuid,full_name text,role text,available_roles text[]) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.is_facility_admin(_facility) THEN RAISE EXCEPTION 'Branch administrator access required' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT uf.user_id,p.full_name,uf.role::text,ARRAY(SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id=uf.user_id AND ur.role::text NOT IN ('superadmin','admin','facility_admin','patient','athlete')) FROM public.user_facilities uf LEFT JOIN public.profiles p ON p.id=uf.user_id WHERE uf.facility_id=_facility;
END $$;
REVOKE ALL ON FUNCTION public.facility_staff_options(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.facility_staff_options(uuid) TO authenticated;
ALTER TABLE public.hr_documents ADD COLUMN IF NOT EXISTS file_name text, ADD COLUMN IF NOT EXISTS storage_path text, ADD COLUMN IF NOT EXISTS mime_type text, ADD COLUMN IF NOT EXISTS effective_date date, ADD COLUMN IF NOT EXISTS facility_id uuid REFERENCES public.facilities(id);
UPDATE public.hr_documents SET storage_path=file_path WHERE storage_path IS NULL AND file_path IS NOT NULL;
UPDATE public.hr_documents SET file_name=regexp_replace(storage_path,'^.*/','') WHERE file_name IS NULL AND storage_path IS NOT NULL;
UPDATE public.hr_documents SET facility_id=public.main_facility_id() WHERE facility_id IS NULL;
CREATE TABLE IF NOT EXISTS public.hr_document_views(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.hr_documents(id) ON DELETE CASCADE,employee_id uuid NOT NULL REFERENCES public.profiles(id),viewed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.hr_document_views TO authenticated;
GRANT ALL ON public.hr_document_views TO service_role;
ALTER TABLE public.hr_document_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own document views" ON public.hr_document_views FOR SELECT TO authenticated USING(employee_id=auth.uid() OR EXISTS(SELECT 1 FROM public.hr_documents d WHERE d.id=document_id AND public.hr_can_manage(d.facility_id)));
CREATE POLICY "Record authorized document opens" ON public.hr_document_views FOR INSERT TO authenticated WITH CHECK(employee_id=auth.uid() AND EXISTS(SELECT 1 FROM public.hr_documents d WHERE d.id=document_id AND public.has_facility_access(d.facility_id) AND (d.published OR public.hr_can_manage(d.facility_id))));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.hr_documents TO authenticated;
GRANT ALL ON public.hr_documents TO service_role;
DROP POLICY IF EXISTS "hrd read" ON public.hr_documents;
DROP POLICY IF EXISTS "hrd write" ON public.hr_documents;
CREATE POLICY "Branch document reads" ON public.hr_documents FOR SELECT TO authenticated USING(public.has_facility_access(facility_id) AND (published OR public.hr_can_manage(facility_id)));
CREATE POLICY "Branch HR document management" ON public.hr_documents FOR ALL TO authenticated USING(public.hr_can_manage(facility_id)) WITH CHECK(public.hr_can_manage(facility_id));
CREATE POLICY "Acknowledgements branch boundary" ON public.hr_document_acks AS RESTRICTIVE FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.hr_documents d WHERE d.id=document_id)) WITH CHECK(EXISTS(SELECT 1 FROM public.hr_documents d WHERE d.id=document_id AND d.published));
DROP POLICY IF EXISTS "hr-docs read" ON storage.objects;
DROP POLICY IF EXISTS "hr-docs write" ON storage.objects;
DROP POLICY IF EXISTS "hr-docs update" ON storage.objects;
DROP POLICY IF EXISTS "hr-docs delete" ON storage.objects;
CREATE POLICY "Staff read authorized HR files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='hr-documents' AND EXISTS(SELECT 1 FROM public.hr_documents d WHERE d.storage_path=name AND public.has_facility_access(d.facility_id) AND (d.published OR public.hr_can_manage(d.facility_id))));
CREATE POLICY "HR upload branch files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='hr-documents' AND (storage.foldername(name))[1] IN (SELECT f.id::text FROM public.facilities f WHERE public.hr_can_manage(f.id)) AND (storage.foldername(name))[2]=auth.uid()::text);
CREATE POLICY "HR remove branch files" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='hr-documents' AND (storage.foldername(name))[1] IN (SELECT f.id::text FROM public.facilities f WHERE public.hr_can_manage(f.id)));
GRANT SELECT ON public.icd11_codes TO authenticated;
CREATE POLICY "Authenticated diagnosis catalog fallback" ON public.icd11_codes FOR SELECT TO authenticated USING(true);
ALTER TABLE public.inventory_items ADD COLUMN IF NOT EXISTS facility_id uuid REFERENCES public.facilities(id);
UPDATE public.inventory_items SET facility_id=public.main_facility_id() WHERE facility_id IS NULL;
ALTER TABLE public.stock_requests ADD COLUMN IF NOT EXISTS facility_id uuid REFERENCES public.facilities(id);
UPDATE public.stock_requests SET facility_id=public.main_facility_id() WHERE facility_id IS NULL;
CREATE POLICY "Inventory branch boundary" ON public.inventory_items AS RESTRICTIVE FOR ALL TO authenticated USING(public.has_facility_access(facility_id)) WITH CHECK(public.has_facility_access(facility_id));
CREATE POLICY "Branch requesters read inventory" ON public.inventory_items FOR SELECT TO authenticated USING(public.facility_has_role(facility_id,ARRAY['nurse','lab_tech','pharmacist','store_keeper','facility_admin','admin']));
CREATE POLICY "Stock request branch boundary" ON public.stock_requests AS RESTRICTIVE FOR ALL TO authenticated USING(public.has_facility_access(facility_id)) WITH CHECK(public.has_facility_access(facility_id));
DROP POLICY IF EXISTS "auth write stock_requests" ON public.stock_requests;
DROP POLICY IF EXISTS "auth read stock_requests" ON public.stock_requests;
DROP POLICY IF EXISTS "store_keeper full stock_requests" ON public.stock_requests;
CREATE POLICY "Requesters and branch store read requests" ON public.stock_requests FOR SELECT TO authenticated USING(requester_id=auth.uid() OR public.facility_has_role(facility_id,ARRAY['store_keeper','facility_admin','admin']));
CREATE POLICY "Store manage branch requests" ON public.stock_requests FOR UPDATE TO authenticated USING(public.facility_has_role(facility_id,ARRAY['store_keeper','admin'])) WITH CHECK(public.facility_has_role(facility_id,ARRAY['store_keeper','admin']));
DROP POLICY IF EXISTS "stock_request_items_staff" ON public.stock_request_items;
DROP POLICY IF EXISTS "store_keeper full stock_request_items" ON public.stock_request_items;
CREATE POLICY "Read own or store request lines" ON public.stock_request_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.stock_requests r WHERE r.id=request_id));
CREATE POLICY "Store update request lines" ON public.stock_request_items FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.stock_requests r WHERE r.id=request_id AND public.facility_has_role(r.facility_id,ARRAY['store_keeper','admin']))) WITH CHECK(EXISTS(SELECT 1 FROM public.stock_requests r WHERE r.id=request_id AND public.facility_has_role(r.facility_id,ARRAY['store_keeper','admin'])));
GRANT SELECT,INSERT,UPDATE ON public.stock_requests,public.stock_request_items TO authenticated;
GRANT ALL ON public.stock_requests,public.stock_request_items TO service_role;
CREATE OR REPLACE FUNCTION public.submit_department_stock_request(_facility uuid,_department text,_notes text,_lines jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE request_id uuid; line jsonb; item uuid; quantity integer;
BEGIN
 IF NOT public.has_facility_access(_facility) OR NOT public.facility_has_role(_facility,CASE _department WHEN 'ward' THEN ARRAY['nurse','admin','facility_admin'] WHEN 'lab' THEN ARRAY['lab_tech','admin','facility_admin'] WHEN 'pharmacy' THEN ARRAY['pharmacist','admin','facility_admin'] ELSE ARRAY[]::text[] END) THEN RAISE EXCEPTION 'Department request access required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.facilities WHERE id=_facility AND is_active) OR EXISTS(SELECT 1 FROM public.facility_modules WHERE facility_id=_facility AND module='inventory' AND NOT enabled) THEN RAISE EXCEPTION 'Stock requests are not enabled for this branch'; END IF;
 IF jsonb_typeof(_lines)<>'array' OR jsonb_array_length(_lines) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Add 1 to 50 stock items'; END IF;
 INSERT INTO public.stock_requests(requester_id,facility_id,department,status,notes) VALUES(auth.uid(),_facility,_department,'submitted',NULLIF(_notes,'')) RETURNING id INTO request_id;
 FOR line IN SELECT value FROM jsonb_array_elements(_lines) LOOP
  item := (line->>'item_id')::uuid; quantity := (line->>'qty')::integer;
  IF quantity IS NULL OR quantity<=0 OR NOT EXISTS(SELECT 1 FROM public.inventory_items WHERE id=item AND facility_id=_facility) THEN RAISE EXCEPTION 'Invalid branch stock item or quantity'; END IF;
  IF EXISTS(SELECT 1 FROM public.stock_request_items WHERE stock_request_items.request_id=submit_department_stock_request.request_id AND item_id=item) THEN RAISE EXCEPTION 'Duplicate stock item'; END IF;
  INSERT INTO public.stock_request_items(request_id,item_id,qty_requested) VALUES(request_id,item,quantity);
 END LOOP;
 RETURN request_id;
END $$;
REVOKE ALL ON FUNCTION public.submit_department_stock_request(uuid,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_department_stock_request(uuid,text,text,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';